function stable(value){if(Array.isArray(value))return value.map(stable);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).filter(([,v])=>v!==undefined).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,stable(v)]));return value}
const serialize=v=>JSON.stringify(stable(v))+'\n'
function transform(project,sx,sy){for(const piece of project.pieces){for(const p of piece.points){p.x*=sx;p.y*=sy}for(const c of Object.values(piece.curves||{})){c.cx*=sx;c.cy*=sy}for(const mark of piece.internalLines||[]){for(const k of ['a','b'])if(mark[k]){mark[k].x*=sx;mark[k].y*=sy}}piece.grainAngleDeg=0;piece.cutQuantity=piece.cutQuantity??1;piece.marker={nap:'one-way',allowCrossGrain:false,allowReverseGrain:false};piece.fabricId=piece.fabricId||'main'}return project}
function digest(str){return crypto.createHash('sha256').update(str).digest('hex')}
const manifest={schema:'exo.golden-garments.v1',revision:'2026-10-28',fixtures:[],notes:['All 25 patterns are deterministic synthetic development fixtures derived from EXO draft templates, not certified factory garments.','Dress cases are deliberately skirt-derived long panel tests, not validated bodice/whole-dress production patterns.','Jacket cases are hooded top prototypes, not independently validated tailored jackets.','Benchmark references describe expected data and geometry invariants; external receiver CAD and sewn sample validations remain outstanding.']}
